public class GroupSeedProbe {
 public static String observe() {
  Map<String,Group> groups=new Map<String,Group>();
  for(Group g:[SELECT Id,DeveloperName,Name,Type,RelatedId,DoesIncludeBosses,DoesSendEmailToMembers FROM Group WHERE DeveloperName IN ('OwnedOrigin','OwnedTarget')]) {groups.put(g.DeveloperName,g);}
  Group origin=groups.get('OwnedOrigin'); Group target=groups.get('OwnedTarget');
  Integer initial=[SELECT count() FROM GroupMember WHERE GroupId=:origin.Id];
  Savepoint sp=Database.setSavepoint();
  try {
   GroupMember membership=new GroupMember(GroupId=origin.Id,UserOrGroupId=UserInfo.getUserId()); insert membership;
   GroupMember stored=[SELECT GroupId,UserOrGroupId FROM GroupMember WHERE Id=:membership.Id];
   Integer inserted=[SELECT count() FROM GroupMember WHERE GroupId=:origin.Id];
   Boolean identity=membership.Id!=null && stored.GroupId==origin.Id && stored.UserOrGroupId==UserInfo.getUserId();
   delete membership;
   Integer remaining=[SELECT count() FROM GroupMember WHERE GroupId=:origin.Id];
   return 'count:'+groups.size()+'|origin:'+origin.DeveloperName+':'+origin.Name+':'+origin.Type+':'+origin.DoesIncludeBosses+':'+origin.DoesSendEmailToMembers
    +'|target:'+target.DeveloperName+':'+target.Name+':'+target.Type+':'+target.DoesIncludeBosses+':'+target.DoesSendEmailToMembers
    +'|related:'+(origin.RelatedId==null && target.RelatedId==null)
    +'|members:'+initial+':'+inserted+':'+remaining+':'+identity
    +'|absent:'+ [SELECT count() FROM Group WHERE DeveloperName='UnprovidedGroup'];
  } finally {Database.rollback(sp);}
 }
}

